    26→
    27→function formatDuration(seconds: number | null): string {
    28→	if (seconds === null) return "N/A";
    29→	if (seconds < 60) return `${seconds}s`;
    30→	const minutes = Math.floor(seconds / 60);
    31→	const remainingSeconds = seconds % 60;
    32→	if (minutes < 60) {
    33→		return remainingSeconds > 0
    34→			? `${minutes}m ${remainingSeconds}s`
    35→			: `${minutes}m`;
    36→	}
    37→	const hours = Math.floor(minutes / 60);
    38→	const remainingMinutes = minutes % 60;
    39→	return remainingMinutes > 0 ? `${hours}h ${remainingMinutes}m` : `${hours}h`;
    40→}
