     1→import type { Question } from "@orksys-survey/db";
     2→import type { ColumnDef } from "@tanstack/react-table";
     3→
     4→interface ResponseRow {
     5→	id: string;
     6→	completedAt: string | null;
     7→	status: string;
     8→	answers: Record<string, unknown>;
     9→}
    10→
    11→export function createResponseColumns(
    12→	questions: Question[],
    13→): ColumnDef<ResponseRow>[] {
    14→	return [
    15→		{
    16→			accessorKey: "id",
    17→			header: "Response ID",
    18→			cell: ({ row }) => (
    19→				<span className="font-mono text-xs">{row.getValue("id")}</span>
    20→			),
    21→		},
    22→		{
    23→			accessorKey: "status",
    24→			header: "Status",
    25→			cell: ({ row }) => {
    26→				const status = row.getValue("status") as string;
    27→				return (
    28→					<span
    29→						className={`inline-flex items-center rounded-full px-2 py-0.5 font-medium text-xs ${
    30→							status === "Complete"
    31→								? "bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200"
    32→								: "bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200"
    33→						}`}
    34→					>
    35→						{status}
    36→					</span>
    37→				);
    38→			},
    39→		},
    40→		{
    41→			accessorKey: "completedAt",
    42→			header: "Date",
    43→			cell: ({ row }) => {
    44→				const date = row.getValue("completedAt") as string | null;
    45→				if (!date) return <span className="text-muted-foreground">—</span>;
    46→				return new Date(date).toLocaleDateString("en-US", {
    47→					month: "short",
    48→					day: "numeric",
    49→					hour: "2-digit",
    50→					minute: "2-digit",
    51→				});
    52→			},
    53→		},
    54→		// Add columns for first 3 questions
    55→		...questions.slice(0, 3).map((q) => ({
    56→			id: `answer-${q.id}`,
    57→			accessorFn: (row: ResponseRow) => row.answers?.[q.id],
    58→			header: q.title.length > 20 ? `${q.title.slice(0, 20)}...` : q.title,
    59→			cell: ({ getValue }: { getValue: () => unknown }) => {
    60→				const value = getValue();
    61→				if (value === null || value === undefined) {
    62→					return <span className="text-muted-foreground">—</span>;
    63→				}
    64→				const strValue =
    65→					typeof value === "string" ? value : JSON.stringify(value);
    66→				return (
    67→					<span className="max-w-[150px] truncate text-sm">
    68→						{strValue.length > 30 ? `${strValue.slice(0, 30)}...` : strValue}
    69→					</span>
    70→				);
    71→			},
    72→		})),
    73→	];
    74→}
    75→
    76→export type { ResponseRow };
