     1→"use client";
     2→
     3→import { Download, QrCode } from "lucide-react";
     4→import QRCodeLib from "qrcode";
     5→import { useEffect, useRef, useState } from "react";
     6→import { Button } from "@/components/ui/button";
     7→import {
     8→	Card,
     9→	CardContent,
    10→	CardDescription,
    11→	CardHeader,
    12→	CardTitle,
    13→} from "@/components/ui/card";
    14→
    15→interface QRCodeGeneratorProps {
    16→	url: string;
    17→	size?: number;
    18→	filename?: string;
    19→}
    20→
    21→export function QRCodeGenerator({
    22→	url,
    23→	size = 256,
    24→	filename = "survey-qr-code.png",
    25→}: QRCodeGeneratorProps) {
    26→	const canvasRef = useRef<HTMLCanvasElement>(null);
    27→	const [imageUrl, setImageUrl] = useState<string>("");
    28→	const [isGenerating, setIsGenerating] = useState(true);
    29→
    30→	useEffect(() => {
    31→		let isMounted = true;
    32→
    33→		const generateQRCode = async () => {
    34→			setIsGenerating(true);
    35→			try {
    36→				if (canvasRef.current) {
    37→					await QRCodeLib.toCanvas(canvasRef.current, url, {
    38→						width: size,
    39→						margin: 2,
    40→						color: {
    41→							dark: "#000000",
    42→							light: "#FFFFFF",
    43→						},
    44→					});
    45→
    46→					if (isMounted) {
    47→						setImageUrl(canvasRef.current.toDataURL("image/png"));
    48→					}
    49→				}
    50→			} catch (error) {
    51→				console.error("Failed to generate QR code:", error);
    52→			} finally {
    53→				if (isMounted) {
    54→					setIsGenerating(false);
    55→				}
    56→			}
    57→		};
    58→
    59→		generateQRCode();
    60→
    61→		return () => {
    62→			isMounted = false;
    63→		};
    64→	}, [url, size]);
    65→
    66→	const handleDownload = () => {
    67→		if (!imageUrl) return;
    68→
    69→		const link = document.createElement("a");
    70→		link.href = imageUrl;
    71→		link.download = filename;
    72→		document.body.appendChild(link);
    73→		link.click();
    74→		document.body.removeChild(link);
    75→	};
    76→
    77→	return (
    78→		<Card>
    79→			<CardHeader>
    80→				<CardTitle className="flex items-center gap-2">
    81→					<QrCode className="h-5 w-5" />
    82→					QR Code
    83→				</CardTitle>
    84→				<CardDescription>
    85→					Download a QR code that links directly to your survey
    86→				</CardDescription>
    87→			</CardHeader>
    88→			<CardContent className="flex flex-col items-center gap-4">
    89→				<div className="flex items-center justify-center rounded-lg border border-neutral-200 bg-neutral-50 p-4">
    90→					{isGenerating ? (
    91→						<div
    92→							className="animate-pulse rounded bg-neutral-200"
    93→							style={{ width: size, height: size }}
    94→						/>
    95→					) : (
    96→						<canvas ref={canvasRef} className="rounded" />
    97→					)}
    98→				</div>
    99→				<Button
   100→					onClick={handleDownload}
   101→					disabled={!imageUrl || isGenerating}
   102→					variant="outline"
   103→					className="w-full"
   104→				>
   105→					<Download className="mr-2 h-4 w-4" />
   106→					Download PNG
   107→				</Button>
   108→			</CardContent>
   109→		</Card>
   110→	);
   111→}
   112→

