    16→
    17→interface RunnerCompleteProps {
    18→	message?: string;
    19→	redirectUrl?: string;
    20→}
    21→
    22→export function RunnerComplete({ message, redirectUrl }: RunnerCompleteProps) {
    23→	const { survey } = useSurveyRunner();
    24→	const router = useRouter();
    25→	const [countdown, setCountdown] = useState(5);
    26→
    27→	// Use props if provided, otherwise fall back to survey settings
    28→	const thankYouMessage =
    29→		message ??
    30→		survey.settings?.thankYouMessage ??
    31→		"Thank you for completing this survey!";
    32→	const finalRedirectUrl = redirectUrl ?? survey.settings?.redirectUrl;
    33→
    34→	// Auto-redirect countdown
    35→	useEffect(() => {
    36→		if (!finalRedirectUrl) return;
    37→
    38→		const timer = setInterval(() => {
    39→			setCountdown((prev) => {
    40→				if (prev <= 1) {
    41→					clearInterval(timer);
    42→					window.location.href = finalRedirectUrl;
    43→					return 0;
    44→				}
    45→				return prev - 1;
    46→			});
    47→		}, 1000);
    48→
    49→		return () => clearInterval(timer);
    50→	}, [finalRedirectUrl]);
    51→
    52→	const handleRedirectNow = () => {
    53→		if (finalRedirectUrl) {
    54→			window.location.href = finalRedirectUrl;
    55→		}
    56→	};
    57→
    58→	return (
    59→		<div className="flex min-h-[50vh] items-center justify-center px-4 py-6">
    60→			<div className="mx-auto w-full max-w-lg">
    61→				<Card>
    62→					<CardHeader className="text-center">
    63→						<div className="mx-auto mb-4 flex size-16 items-center justify-center rounded-full bg-green-100">
    64→							<CheckCircle2 className="size-8 text-green-600" />
    65→						</div>
    66→						<CardTitle className="text-2xl">Survey Complete</CardTitle>
    67→					</CardHeader>
    68→
    69→					<CardContent className="text-center">
    70→						<p className="text-neutral-700">{thankYouMessage}</p>
    71→
    72→						{finalRedirectUrl && countdown > 0 && (
    73→							<p className="mt-4 text-neutral-500 text-sm">
    74→								Redirecting in {countdown} seconds...
    75→							</p>
    76→						)}
    77→					</CardContent>
    78→
    79→					<CardFooter className="flex flex-col gap-2">
    80→						{finalRedirectUrl && (
    81→							<Button
    82→								variant="default"
    83→								className="w-full"
    84→								onClick={handleRedirectNow}
    85→							>
    86→								Continue
    87→								<ExternalLink className="ml-2 size-4" />
    88→							</Button>
    89→						)}
    90→
    91→						<Button
    92→							variant="outline"
    93→							className="w-full"
    94→							onClick={() => router.push(`/s/${survey.slug}`)}
    95→						>
    96→							Back to Survey
    97→						</Button>
    98→					</CardFooter>
    99→				</Card>
   100→			</div>
   101→		</div>
   102→	);
   103→}
