    20→import { LogicRuleForm } from "./logic-rule-form";
    21→import { RuleListItem } from "./rule-list-item";
    22→
    23→interface LogicBuilderProps {
    24→	surveyId: string;
    25→	questions: Question[];
    26→	selectedQuestionId: string | null;
    27→}
    28→
    29→export function LogicBuilder({
    30→	surveyId,
    31→	questions,
    32→	selectedQuestionId,
    33→}: LogicBuilderProps) {
    34→	const queryClient = useQueryClient();
    35→	const [isDialogOpen, setIsDialogOpen] = useState(false);
    36→	const [editingRule, setEditingRule] = useState<LogicRule | null>(null);
    37→	const [deleteRuleId, setDeleteRuleId] = useState<string | null>(null);
    38→
    39→	const logicRules = useQuery(
    40→		orpc.logicRule.list.queryOptions({ input: { surveyId } }),
    41→	);
    42→
    43→	const deleteMutation = useMutation(
    44→		orpc.logicRule.delete.mutationOptions({
    45→			onSuccess: () => {
    46→				toast.success("Logic rule deleted");
    47→				queryClient.invalidateQueries({ queryKey: ["logicRule"] });
    48→				setDeleteRuleId(null);
    49→			},
    50→			onError: (error) => {
    51→				toast.error(error.message || "Failed to delete logic rule");
    52→			},
    53→		}),
    54→	);
    55→
    56→	// Filter rules for the selected question
    57→	const questionRules = selectedQuestionId
    58→		? logicRules.data?.filter(
    59→				(rule) => rule.sourceQuestionId === selectedQuestionId,
    60→			)
    61→		: [];
    62→
    63→	const handleDelete = (ruleId: string) => {
    64→		setDeleteRuleId(ruleId);
    65→	};
    66→
    67→	const confirmDelete = () => {
    68→		if (deleteRuleId) {
    69→			deleteMutation.mutate({ id: deleteRuleId });
    70→		}
    71→	};
    72→
    73→	const handleFormSuccess = () => {
    74→		setIsDialogOpen(false);
    75→		setEditingRule(null);
    76→		queryClient.invalidateQueries({ queryKey: ["logicRule"] });
    77→	};
    78→
    79→	if (!selectedQuestionId) {
    80→		return (
    81→			<div className="rounded-xl border border-violet-100 bg-violet-50 p-4">
    82→				<div className="mb-3 flex items-center gap-2">
    83→					<Bolt className="h-4 w-4 text-violet-500" />
    84→					<span className="font-semibold text-neutral-900 text-sm">
    85→						Skip Logic
    86→					</span>
    87→				</div>
    88→				<p className="text-neutral-600 text-xs leading-relaxed">
    89→					Select a question to add skip logic.
    90→				</p>
    91→			</div>
    92→		);
    93→	}
    94→
    95→	const selectedQuestion = questions.find((q) => q.id === selectedQuestionId);
    96→	const targetQuestions = questions.filter(
    97→		(q) => q.order > (selectedQuestion?.order ?? 0),
    98→	);
    99→
   100→	return (
   101→		<>
   102→			<div className="space-y-3">
   103→				<div className="flex items-center justify-between">
   104→					<div className="flex items-center gap-2">
   105→						<Bolt className="h-4 w-4 text-violet-500" />
   106→						<span className="font-semibold text-neutral-900 text-sm">
   107→							Skip Logic
   108→						</span>
   109→						{questionRules && questionRules.length > 0 && (
   110→							<span className="flex h-5 w-5 items-center justify-center rounded-full bg-violet-100 font-medium text-violet-600 text-xs">
   111→								{questionRules.length}
   112→							</span>
   113→						)}
   114→					</div>
   115→				</div>
   116→
   117→				{logicRules.isLoading ? (
   118→					<div className="flex justify-center py-4">
   119→						<Loader2 className="h-4 w-4 animate-spin text-neutral-400" />
   120→					</div>
   121→				) : questionRules && questionRules.length > 0 ? (
   122→					<div className="space-y-2">
   123→						{questionRules.map((rule) => (
   124→							<RuleListItem
   125→								key={rule.id}
   126→								rule={rule}
   127→								allQuestions={questions}
   128→								onEdit={(r) => {
   129→									setEditingRule(r);
   130→									setIsDialogOpen(true);
   131→								}}
   132→								onDelete={handleDelete}
   133→								isDeleting={deleteMutation.isPending}
   134→							/>
   135→						))}
   136→					</div>
   137→				) : (
   138→					<p className="text-neutral-500 text-xs">
   139→						No logic rules for this question.
   140→					</p>
   141→				)}
   142→
   143→				<Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
   144→					<DialogTrigger asChild>
   145→						<Button
   146→							variant="outline"
   147→							size="sm"
   148→							className="w-full border-violet-200 text-violet-600 hover:bg-violet-50"
   149→						>
   150→							<Plus className="mr-2 h-4 w-4" />
   151→							Add Rule
   152→						</Button>
   153→					</DialogTrigger>
   154→					<DialogContent className="max-w-md">
   155→						<DialogHeader>
   156→							<DialogTitle>
   157→								{editingRule ? "Edit Logic Rule" : "Add Logic Rule"}
   158→							</DialogTitle>
   159→						</DialogHeader>
   160→						<LogicRuleForm
   161→							surveyId={surveyId}
   162→							questions={questions}
   163→							sourceQuestionId={selectedQuestionId}
   164→							targetQuestions={targetQuestions}
   165→							existingRule={
   166→								editingRule
   167→									? {
   168→											id: editingRule.id,
   169→											operator: editingRule.operator,
   170→											action: editingRule.action,
   171→											conditionValue:
   172→												editingRule.conditionValue !== null &&
   173→												editingRule.conditionValue !== undefined
   174→													? String(editingRule.conditionValue)
   175→													: null,
   176→											targetQuestionId: editingRule.targetQuestionId,
   177→										}
   178→									: null
   179→							}
   180→							onSuccess={handleFormSuccess}
   181→							onCancel={() => {
   182→								setIsDialogOpen(false);
   183→								setEditingRule(null);
   184→							}}
   185→						/>
   186→					</DialogContent>
   187→				</Dialog>
   188→			</div>
   189→
   190→			<Dialog open={!!deleteRuleId} onOpenChange={() => setDeleteRuleId(null)}>
   191→				<DialogContent className="max-w-md">
   192→					<DialogHeader>
   193→						<DialogTitle>Delete Logic Rule</DialogTitle>
   194→						<DialogDescription>
   195→							Are you sure you want to delete this logic rule? This action
   196→							cannot be undone.
   197→						</DialogDescription>
   198→					</DialogHeader>
   199→					<DialogFooter>
   200→						<Button variant="outline" onClick={() => setDeleteRuleId(null)}>
   201→							Cancel
   202→						</Button>
   203→						<Button variant="destructive" onClick={confirmDelete}>
   204→							Delete
   205→						</Button>
   206→					</DialogFooter>
   207→				</DialogContent>
   208→			</Dialog>
   209→		</>
   210→	);
   211→}
