    12→import React from "react";
    13→import { toast } from "sonner";
    14→
    15→import { Button } from "@/components/ui/button";
    16→import { Card, CardContent } from "@/components/ui/card";
    17→import { orpc } from "@/utils/orpc";
    18→import { useSurveyBuilder } from "../index";
    19→import { QuestionCard } from "../question-card";
    20→import { createMockQuestion } from "../utils";
    21→import { DropIndicator } from "./drop-indicator";
    22→import { PreviewCanvas } from "./preview-canvas";
    23→import { ShareCanvas } from "./share-canvas";
    24→
    25→// Drag item types
    26→export interface PaletteDragItem {
    27→	type: "palette";
    28→	questionType: Question["type"];
    29→}
    30→
    31→export interface QuestionDragItem {
    32→	type: "question";
    33→	id: string;
    34→}
    35→
    36→export type DragItem = PaletteDragItem | QuestionDragItem;
    37→
    38→interface BuilderCanvasProps {
    39→	questions: Question[];
    40→	onQuestionsChange: (questions: Question[]) => void;
    41→	activeDragItem: DragItem | null;
    42→	overId: string | null;
    43→}
    44→
    45→export function BuilderCanvas({
    46→	questions,
    47→	onQuestionsChange,
    48→	activeDragItem,
    49→	overId,
    50→}: BuilderCanvasProps) {
    51→	const { survey, selectedQuestionId, setSelectedQuestionId, activeTab } =
    52→		useSurveyBuilder();
    53→
    54→	const queryClient = useQueryClient();
    55→
    56→	// Make canvas droppable
    57→	const { setNodeRef, isOver } = useDroppable({
    58→		id: "canvas",
    59→	});
    60→
    61→	const safeQuestions = questions || [];
    62→
    63→	const createMutation = useMutation(
    64→		orpc.question.create.mutationOptions({
    65→			onSuccess: (newQuestion) => {
    66→				onQuestionsChange([...questions, newQuestion]);
    67→				setSelectedQuestionId(newQuestion.id);
    68→				queryClient.invalidateQueries({ queryKey: ["question"] });
    69→				toast.success("Question added");
    70→			},
    71→			onError: (error) => {
    72→				toast.error(error.message || "Failed to create question");
    73→			},
    74→		}),
    75→	);
    76→
    77→	const handleAddQuestion = () => {
    78→		createMutation.mutate({
    79→			surveyId: survey.id,
    80→			type: "text",
    81→			title: "New Question",
    82→			order: safeQuestions.length,
    83→		});
    84→	};
    85→
    86→	// Render different tabs
    87→	if (activeTab === "share") {
    88→		return <ShareCanvas slug={survey.slug} />;
    89→	}
    90→
    91→	if (activeTab === "preview") {
    92→		return <PreviewCanvas questions={safeQuestions} />;
    93→	}
    94→
    95→	// Calculate drop position based on overId
    96→	const rawDropIndex = overId
    97→		? safeQuestions.findIndex((q) => q.id === overId)
    98→		: -1;
    99→	const dropIndex = rawDropIndex === -1 ? safeQuestions.length : rawDropIndex;
   100→
   101→	// Get the question type being dragged
   102→	const isDraggingPalette = activeDragItem?.type === "palette";
   103→	const draggedQuestionType = isDraggingPalette
   104→		? activeDragItem.questionType
   105→		: undefined;
   106→
   107→	return (
   108→		<div
   109→			ref={setNodeRef}
   110→			className={`flex flex-1 flex-col overflow-y-auto bg-neutral-50/50 p-6 transition-colors ${
   111→				isOver ? "bg-violet-50/50" : ""
   112→			}`}
   113→		>
   114→			<div className="mx-auto w-full max-w-2xl space-y-3">
   115→				<AnimatePresence mode="popLayout" initial={false}>
   116→					{safeQuestions.length === 0 ? (
   117→						<EmptyCanvas
   118→							isOver={isOver}
   119→							onAddQuestion={handleAddQuestion}
   120→							isPending={createMutation.isPending}
   121→						/>
   122→					) : (
   123→						<>
   124→							<SortableContext
   125→								items={safeQuestions.map((q) => q.id)}
   126→								strategy={verticalListSortingStrategy}
   127→							>
   128→								{safeQuestions.map((question, index) => (
   129→									<React.Fragment key={question.id}>
   130→										{/* Add drop indicator before this question if dragging over it */}
   131→										{isDraggingPalette &&
   132→											index === dropIndex &&
   133→											draggedQuestionType && (
   134→												<DropIndicator
   135→													questionType={draggedQuestionType}
   136→													position="middle"
   137→												/>
   138→											)}
   139→
   140→										{/* Add the question card */}
   141→										<motion.div
   142→											layout={!activeDragItem ? "position" : false}
   143→											initial={
   144→												question.id.startsWith("temp-")
   145→													? { opacity: 0, y: 20, scale: 0.95 }
   146→													: false
   147→											}
   148→											animate={{ opacity: 1, y: 0, scale: 1 }}
   149→											exit={{
   150→												opacity: 0,
   151→												scale: 0.95,
   152→												transition: { duration: 0.15 },
   153→											}}
   154→											transition={{
   155→												type: "spring",
   156→												stiffness: 400,
   157→												damping: 30,
   158→												mass: 0.8,
   159→											}}
   160→										>
   161→											<QuestionCard
   162→												question={question}
   163→												isSelected={selectedQuestionId === question.id}
   164→												onSelect={() => setSelectedQuestionId(question.id)}
   165→												questions={safeQuestions}
   166→												onQuestionsChange={onQuestionsChange}
   167→											/>
   168→										</motion.div>
   169→									</React.Fragment>
   170→								))}
   171→
   172→								{/* Add indicator at end if hovering at last position or over canvas */}
   173→								{isDraggingPalette &&
   174→									dropIndex >= safeQuestions.length &&
   175→									draggedQuestionType && (
   176→										<DropIndicator
   177→											questionType={draggedQuestionType}
   178→											position="end"
   179→										/>
   180→									)}
   181→							</SortableContext>
   182→
   183→							<motion.div
   184→								initial={{ opacity: 0 }}
   185→								animate={{ opacity: 1 }}
   186→								transition={{ delay: 0.1 }}
   187→							>
   188→								<Button
   189→									variant="outline"
   190→									className="w-full border-dashed"
   191→									onClick={handleAddQuestion}
   192→									disabled={createMutation.isPending}
   193→								>
   194→									<Plus className="mr-2 h-4 w-4" />
   195→									Add Question
   196→								</Button>
   197→							</motion.div>
   198→						</>
   199→					)}
   200→				</AnimatePresence>
   201→			</div>
   202→		</div>
   203→	);
   204→}
   205→
   206→interface EmptyCanvasProps {
   207→	isOver: boolean;
   208→	onAddQuestion: () => void;
   209→	isPending: boolean;
   210→}
   211→
   212→function EmptyCanvas({ isOver, onAddQuestion, isPending }: EmptyCanvasProps) {
   213→	return (
   214→		<motion.div
   215→			key="empty-state"
   216→			initial={{ opacity: 0, scale: 0.95 }}
   217→			animate={{ opacity: 1, scale: 1 }}
   218→			exit={{ opacity: 0, scale: 0.95 }}
   219→			transition={{ duration: 0.2 }}
   220→		>
   221→			<Card
   222→				className={`cursor-pointer border-dashed transition-colors hover:border-violet-300 hover:bg-violet-50/50 ${
   223→					isOver ? "border-violet-400 bg-violet-50" : ""
   224→				}`}
   225→				onClick={onAddQuestion}
   226→			>
   227→				<CardContent className="flex flex-col items-center justify-center py-16">
   228→					<motion.div
   229→						className="mb-4 rounded-full bg-violet-100 p-4"
   230→						animate={isOver ? { scale: 1.1 } : { scale: 1 }}
   231→						transition={{ type: "spring", stiffness: 400, damping: 17 }}
   232→					>
   233→						<Plus className="h-8 w-8 text-violet-500" />
   234→					</motion.div>
   235→					<p className="font-semibold text-neutral-900">
   236→						Add your first question
   237→					</p>
   238→					<p className="mt-1 text-neutral-500 text-sm">
   239→						Click here or drag a question type from the left panel
   240→					</p>
   241→				</CardContent>
   242→			</Card>
   243→		</motion.div>
   244→	);
   245→}
