// Compound component types
export interface QuestionCardBadgeProps {
	children: React.ReactNode;
	className?: string;
}

export interface QuestionCardActionsProps {
	onDelete?: () => void;
	isDeleting?: boolean;
	className?: string;
}

// Context for sharing question card state with compound components
interface QuestionCardContextValue {
	question: Question;
	isOverlay?: boolean;
	isSelected?: boolean;
}

const QuestionCardContext = createContext<QuestionCardContextValue | null>(
	null,
);

function useQuestionCardContext() {
	const context = useContext(QuestionCardContext);
	if (!context) {
		throw new Error(
			"QuestionCard compound components must be used within QuestionCard",
		);
	}
	return context;
}

interface QuestionCardProps {
	question: Question;
	isSelected: boolean;
	onSelect: () => void;
	questions: Question[];
	onQuestionsChange: (questions: Question[]) => void;
	children?: React.ReactNode;
}

const animateLayoutChanges: AnimateLayoutChanges = () => {
	return false;
};

export const QuestionCard = memo(function QuestionCard({
	question,
	isSelected,
	onSelect,
	questions,
	onQuestionsChange,
	children,
}: QuestionCardProps) {
	const queryClient = useQueryClient();

	// Sortable for reordering within canvas
	const {
		attributes,
		listeners,
		setNodeRef: setSortableRef,
		transform,
		transition,
		isDragging,
	} = useSortable({
		id: question.id,
		animateLayoutChanges,
	});

	// Droppable for palette item drops
	const { setNodeRef: setDroppableRef, isOver } = useDroppable({
		id: question.id,
	});

	// Combine refs so element is both sortable and droppable
	const setNodeRef = (node: HTMLElement | null) => {
		setSortableRef(node);
		setDroppableRef(node);
	};

	const deleteMutation = useMutation(
		orpc.question.delete.mutationOptions({
			onSuccess: () => {
				onQuestionsChange(questions.filter((q) => q.id !== question.id));
				queryClient.invalidateQueries({ queryKey: ["question"] });
				toast.success("Question deleted");
			},
			onError: (error) => {
				toast.error(error.message || "Failed to delete question");
			},
		}),
	);

	// Query logic rules to check if this question has any
	const logicRules = useQuery(
		orpc.logicRule.list.queryOptions({
			input: { surveyId: question.surveyId },
		}),
	);

	const hasLogic = logicRules.data?.some(
		(rule) => rule.sourceQuestionId === question.id,
	);

	const style = {
		transform: CSS.Translate.toString(transform),
		transition,
		zIndex: isDragging ? 50 : undefined,
	};

	const contextValue: QuestionCardContextValue = {
		question,
		isOverlay: false,
		isSelected,
	};

	return (
		<QuestionCardContext.Provider value={contextValue}>
			<motion.div
				ref={setNodeRef}
				style={style}
				className={cn(isDragging && "z-50")}
			>
				<QuestionCardContent
					question={question}
					isSelected={isSelected}
					hasLogic={hasLogic}
					onSelect={onSelect}
					dragHandleProps={{ ...attributes, ...listeners }}
					isDragging={isDragging}
					isOver={isOver}
				>
					<QuestionCardActions
						onDelete={() => deleteMutation.mutate({ id: question.id })}
						isDeleting={deleteMutation.isPending}
					/>
				</QuestionCardContent>
			</motion.div>
		</QuestionCardContext.Provider>
	);
});

// Badge component for displaying question metadata
export const QuestionCardBadge = function QuestionCardBadge({
	children,
	className,
}: QuestionCardBadgeProps) {
	const { question } = useQuestionCardContext();
	return (
		<motion.span
			initial={{ opacity: 0, scale: 0.8 }}
			animate={{ opacity: 1, scale: 1 }}
			className={cn(
				"flex items-center gap-1 rounded bg-violet-100 px-1.5 py-0.5 font-medium text-[10px] text-violet-600",
				className,
			)}
		>
			{children}
		</motion.span>
	);
};

// Actions component for question card actions (delete, etc.)
export const QuestionCardActions = function QuestionCardActions({
	onDelete,
	isDeleting = false,
	className,
}: QuestionCardActionsProps) {
	const { question, isSelected, isOverlay } = useQuestionCardContext();

	if (isOverlay || !onDelete) {
		return null;
	}

	return (
		<DeleteConfirmButton
			onDelete={onDelete}
			isDeleting={isDeleting}
			className={cn(
				"opacity-0 transition-opacity group-hover:opacity-100 data-[selected=true]:opacity-100",
				className,
			)}
			data-selected={isSelected}
		/>
	);
};

// Export the content component for external use
export { QuestionCardContent };

"use client";

import { Progress } from "@/components/ui/progress";
import { useSurveyRunner } from "./context";

export function RunnerProgress() {
	const { settings, visibleQuestions, answers } = useSurveyRunner();

	if (!settings?.showProgressBar) {
		return null;
	}

	// Calculate progress based on answered visible questions
	const answeredCount = visibleQuestions.filter((q) => {
		const answer = answers.get(q.id);
		return answer !== undefined && answer !== null && answer !== "";
	}).length;

	const progress = (answeredCount / visibleQuestions.length) * 100;

	return (
		<div className="px-6 py-3">
			<div className="mx-auto max-w-2xl">
				<div className="mb-1.5 flex items-center justify-between text-neutral-500 text-xs">
					<span>Progress</span>
					<span>{Math.round(progress)}%</span>
				</div>
				<Progress value={progress} max={100} />
			</div>
		</div>
	);
}

import { QuestionField } from "./question-field";
import type { ArrayQuestionProps, TextQuestionProps } from "./types";

interface SingleChoiceProps extends TextQuestionProps {
	options: Array<{ value: string; label: string }>;
}

interface MultipleChoiceProps extends ArrayQuestionProps {
	options: Array<{ value: string; label: string }>;
}

function SingleChoice({
	question,
	value,
	onChange,
	options,
}: SingleChoiceProps) {
	return (
		<QuestionField question={question} error={undefined}>
			<div className="mt-3 space-y-2">
				{options.map((option) => (
					<label
						key={option.value}
						className="flex cursor-pointer items-center gap-3 rounded-lg border border-neutral-200 p-3 transition-colors hover:bg-neutral-50 has-[:checked]:border-neutral-500 has-[:checked]:bg-neutral-50"
					>
						<input
							type="radio"
							name={question.id}
							value={option.value}
							checked={value === option.value}
							onChange={(e) => onChange(e.target.value)}
							className="h-4 w-4 text-neutral-900"
						/>
						<span className="text-neutral-900">{option.label}</span>
					</label>
				))}
			</div>
		</QuestionField>
	);
}

function MultipleChoice({
	question,
	value,
	onChange,
	options,
}: MultipleChoiceProps) {
	const selectedValues = value ?? [];

	const handleToggle = (optionValue: string) => {
		if (selectedValues.includes(optionValue)) {
			onChange(selectedValues.filter((v) => v !== optionValue));
		} else {
			onChange([...selectedValues, optionValue]);
		}
	};

	return (
		<QuestionField question={question} error={undefined}>
			<div className="mt-3 space-y-2">
				{options.map((option) => (
					<label
						key={option.value}
						className="flex cursor-pointer items-center gap-3 rounded-lg border border-neutral-200 p-3 transition-colors hover:bg-neutral-50 has-[:checked]:border-neutral-500 has-[:checked]:bg-neutral-50"
					>
						<input
							type="checkbox"
							checked={selectedValues.includes(option.value)}
							onChange={() => handleToggle(option.value)}
							className="h-4 w-4 rounded text-neutral-900"
						/>
						<span className="text-neutral-900">{option.label}</span>
					</label>
				))}
			</div>
		</QuestionField>
	);
}

export function ChoiceQuestion(props: TextQuestionProps) {
	const options = props.question.config?.options ?? [];
	return <SingleChoice {...props} options={options} />;
}

export function CheckboxQuestion(props: ArrayQuestionProps) {
	const options = props.question.config?.options ?? [];
	return <MultipleChoice {...props} options={options} />;
}

