import { QuestionField } from "./question-field";
import type { TextQuestionProps } from "./types";

export function DateQuestion({ question, value, onChange }: TextQuestionProps) {
	return (
		<QuestionField question={question} error={undefined}>
			<input
				type="date"
				value={value ?? ""}
				onChange={(e) => onChange(e.target.value)}
				className="w-full rounded-lg border border-neutral-300 px-4 py-2.5 text-neutral-900 focus:border-neutral-500 focus:outline-none focus:ring-1 focus:ring-neutral-500"
			/>
		</QuestionField>
	);
}

import { QuestionField } from "./question-field";
import type { BaseQuestionProps } from "./types";

export function FileUploadQuestion({ question, error }: BaseQuestionProps) {
	const maxFiles = question.config?.maxFiles ?? 1;

	return (
		<QuestionField question={question} error={error}>
			<div className="mt-3 flex justify-center rounded-lg border border-neutral-300 border-dashed px-6 py-10">
				<div className="text-center">
					<p className="text-neutral-600 text-sm">
						Drag and drop files here, or click to select
					</p>
					<p className="mt-1 text-neutral-500 text-xs">
						Up to {maxFiles} file{maxFiles > 1 ? "s" : ""}
					</p>
				</div>
			</div>
		</QuestionField>
	);
}

