					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "rating":
			return (
				<RatingQuestion
					question={question}
					value={value as number | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "nps":
			return (
				<NpsQuestion
					question={question}
					value={value as number | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "linear_scale":
			return (
				<LinearScaleQuestion
					question={question}
					value={value as number | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "date":
			return (
				<DateQuestion
					question={question}
					value={value as string | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "email":
			return (
				<EmailQuestion
					question={question}
					value={value as string | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "phone":
			return (
				<PhoneQuestion
					question={question}
					value={value as string | undefined}
					onChange={(v) => handleChange(v)}
					error={error}
				/>
			);
		case "file_upload":
			return (
				<FileUploadQuestion
					question={question}
					value={value}
					onChange={handleChange}
					error={error}
				/>
			);
		default:
