						<p className="mt-1 text-amber-700 text-xs">
							Circular dependency detected in logic rules.
						</p>
					)}
					{validateQuery.data.selfReferentialRules.length > 0 && (
						<p className="mt-1 text-amber-700 text-xs">
							Some rules reference themselves.
						</p>
					)}
				</div>
			)}

			{/* Actions */}
			<div className="flex gap-3 pt-4">
				<Button
					type="button"
					variant="outline"
					onClick={onCancel}
					className="flex-1"
				>
					Cancel
				</Button>
