					{(state: any) => (
						<Button
							type="submit"
							disabled={!state.canSubmit || isSubmitting}
							className="flex-1"
						>
							{isSubmitting ? (
								<Loader2 className="h-4 w-4 animate-spin" />
							) : existingRule ? (
								"Update Rule"
							) : (
								"Create Rule"
							)}
						</Button>
					)}
				</form.Subscribe>
			</div>
		</form>
	);
}

